const lockAgentMCPDelegationAdmission = `-- name: LockAgentMCPDelegationAdmission :one
WITH locked_agent AS MATERIALIZED (
    SELECT agent.id, agent.workspace_id, agent.name, agent.avatar_url, agent.runtime_mode, agent.runtime_config, agent.visibility, agent.status, agent.max_concurrent_tasks, agent.owner_id, agent.created_at, agent.updated_at, agent.description, agent.runtime_id, agent.instructions, agent.archived_at, agent.archived_by, agent.custom_env, agent.custom_args, agent.mcp_config, agent.model, agent.thinking_level, agent.composio_toolkit_allowlist, agent.permission_mode, agent.kind, agent.system_key
    FROM agent
    JOIN agent_runtime runtime
      ON runtime.id = agent.runtime_id
     AND runtime.workspace_id = agent.workspace_id
    JOIN member owner_member
      ON owner_member.workspace_id = agent.workspace_id
     AND owner_member.user_id = agent.owner_id
    WHERE agent.id = $4
      AND agent.workspace_id = $5
      AND agent.owner_id = $6
      AND agent.archived_at IS NULL
      AND agent.runtime_id IS NOT NULL
    FOR SHARE OF agent, runtime
), locked_endpoint AS MATERIALIZED (
    SELECT endpoint.id, endpoint.workspace_id, endpoint.agent_id, endpoint.public_agent_id, endpoint.enabled, endpoint.delegated_by_user_id, endpoint.card_name, endpoint.card_description, endpoint.card_version, endpoint.card_skills, endpoint.created_at, endpoint.updated_at
    FROM agent_a2a_endpoint endpoint
    JOIN locked_agent agent
      ON agent.id = endpoint.agent_id
     AND agent.workspace_id = endpoint.workspace_id
     AND agent.owner_id = endpoint.delegated_by_user_id
    WHERE endpoint.id = $1
      AND endpoint.public_agent_id = $7
    FOR SHARE OF endpoint
), locked_client AS MATERIALIZED (
    SELECT client.id, client.endpoint_id, client.name, client.status, client.scopes, client.rate_limit_per_minute, client.max_concurrent_tasks, client.created_by, client.updated_by, client.revoked_at, client.revoked_by, client.created_at, client.updated_at
    FROM a2a_client client
    JOIN locked_endpoint endpoint ON endpoint.id = client.endpoint_id
    WHERE client.id = $2
      AND client.status = 'active'
      AND 'send' = ANY(client.scopes)
    FOR SHARE OF client
), locked_credential AS MATERIALIZED (
    SELECT credential.id, credential.client_id, credential.key_id, credential.token_hash, credential.token_prefix, credential.status, credential.expires_at, credential.last_used_at, credential.created_by, credential.revoked_at, credential.revoked_by, credential.created_at, credential.updated_at
    FROM a2a_client_credential credential
    JOIN locked_client client ON client.id = credential.client_id
    WHERE credential.id = $8
      AND credential.status = 'active'
      AND (credential.expires_at IS NULL OR credential.expires_at > now())
    FOR SHARE OF credential
)
SELECT delegation.id, delegation.endpoint_id, delegation.client_id, delegation.accepted_credential_id, delegation.public_task_id, delegation.request_id, delegation.request_fingerprint, delegation.operation, delegation.issue_id, delegation.root_local_task_id, delegation.created_at, delegation.updated_at
FROM agent_mcp_delegation delegation
JOIN locked_endpoint endpoint ON endpoint.id = delegation.endpoint_id
JOIN locked_client client ON client.id = delegation.client_id
JOIN locked_credential credential ON TRUE
WHERE delegation.endpoint_id = $1
  AND delegation.client_id = $2
  AND delegation.request_id = $3
FOR NO KEY UPDATE OF delegation
`

type LockAgentMCPDelegationAdmissionParams struct {
	EndpointID    pgtype.UUID `json:"endpoint_id"`
	ClientID      pgtype.UUID `json:"client_id"`
	RequestID     string      `json:"request_id"`
	AgentID       pgtype.UUID `json:"agent_id"`
	WorkspaceID   pgtype.UUID `json:"workspace_id"`
	OwnerID       pgtype.UUID `json:"owner_id"`
	PublicAgentID string      `json:"public_agent_id"`
	CredentialID  pgtype.UUID `json:"credential_id"`
}

// A follow-up comment is inserted by IssueCommentService on a separate
// transaction and references this row through a foreign key. NO KEY UPDATE
// still serializes callers changing the claim while remaining compatible
// with the FK's KEY SHARE lock.
func (q *Queries) LockAgentMCPDelegationAdmission(ctx context.Context, arg LockAgentMCPDelegationAdmissionParams) (AgentMcpDelegation, error) {
	row := q.db.QueryRow(ctx, lockAgentMCPDelegationAdmission,
		arg.EndpointID,
		arg.ClientID,
		arg.RequestID,
		arg.AgentID,
		arg.WorkspaceID,
		arg.OwnerID,
		arg.PublicAgentID,
		arg.CredentialID,
	)
	var i AgentMcpDelegation
	err := row.Scan(
		&i.ID,
		&i.EndpointID,
		&i.ClientID,
		&i.AcceptedCredentialID,
		&i.PublicTaskID,
		&i.RequestID,
		&i.RequestFingerprint,
		&i.Operation,
		&i.IssueID,
		&i.RootLocalTaskID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

